using System.Globalization;
using System.Text.Json;

namespace ReiksViewer;

/// <summary>
/// The app's texts in the user's language. The tables are the lang/*.json files, embedded in
/// the program; they are generated by lang/make_languages.py.
/// </summary>
public static class L
{
    /// <summary>The languages on offer, each named in its own language.</summary>
    public static readonly (string Code, string Name)[] Languages =
    {
        ("en", "English"),
        ("es", "Español"),
        ("sv", "Svenska"),
        ("fr", "Français"),
        ("de", "Deutsch"),
        ("pt", "Português"),
        ("it", "Italiano"),
    };

    static readonly Dictionary<string, string> English = Load("en");
    static Dictionary<string, string> _current = English;

    public static string Code { get; private set; } = "en";

    /// <summary>
    /// Switches language. An empty code means "follow Windows"; a language the app doesn't
    /// have falls back to English.
    /// </summary>
    public static void Use(string? code)
    {
        if (string.IsNullOrEmpty(code)) code = CultureInfo.CurrentUICulture.TwoLetterISOLanguageName;
        if (!Languages.Any(language => language.Code == code)) code = "en";
        Code = code;
        _current = code == "en" ? English : Load(code);
    }

    /// <summary>The text for a key, in the current language, or in English if it is missing there.</summary>
    public static string T(string key) =>
        _current.TryGetValue(key, out var text) || English.TryGetValue(key, out text) ? text : key;

    public static string T(string key, params object[] values) => string.Format(T(key), values);

    static Dictionary<string, string> Load(string code)
    {
        using var stream = typeof(L).Assembly.GetManifestResourceStream($"lang.{code}.json");
        return stream == null
            ? new Dictionary<string, string>()
            : JsonSerializer.Deserialize<Dictionary<string, string>>(stream) ?? new Dictionary<string, string>();
    }
}
